function IGUILayout:load()
    local startLoadTime = os.clock() * 1000
    if not self:isNeedLoad() then
        return
    end
    if string.find(self.__name, ".json") then
        self.root = GUIManager:loadWindowFromFile(self.__name, false)
    else
        self.root = GUIManager:getWindowByName(self.__name)
    end
    if not self.root then
        LogUtil.logScriptException(string.format("IGUILayout:load() Can't find window json [%s]", self.__name))
        return
    end
    if string.find(self.__name, ".json") then
        GUIManager:addLayout(self, self.parent)
    end
    self:setRoot(self.root)
    self:onLoad()
    LogUtil.logInfo("IGUILayout:load()", self.__name, "LoadTime=" .. (os.clock() * 1000 - startLoadTime))
end

