end

function IGUILayout:hide()
    if ClientHelper.getBoolPrefs("LockUIShowAndHide") and not self:isIgnoreLock() then
        return
    end
    if not self:isLoad() then
        return
    end
    if self:isAlwaysShow() then
        return
    end
    if not self:isShow() then
        return
    end
    self.root:SetVisible(false)
    self:onHide()
    Events.GUILayoutHideEvent:invoke(self.__name)

    if Platform.isWindow() and GuideSystemSetting.onWindowHidden then
        GuideSystemSetting.onWindowHidden(self.__name)
    end

    LogUtil.log("IGUILayout:onHide[" .. self.__name .. "]")
end

